import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, positionWorld, vec2, vec3, color, mix, sub, mul, sin, fract, dot, add } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const byRole = (role) => items.filter((i) => i.role === role).map((i) => i.text);
  const kickerText = byRole('kicker')[0] ?? 'NOVA ATELIER / JOURNAL';
  const heroLines = byRole('hero');
  const heroLine1 = heroLines[0] ?? 'PRECISION IS';
  const heroLine2 = heroLines[1] ?? 'A HABIT.';
  const bodyText = byRole('body')[0] ?? 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.';
  const captionText = byRole('caption')[0] ?? 'ISSUE 12 / JULY 2026';

  const { Group, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const timelines = [];

  // —— backdrop: vertical gradient + 1.5% monochrome grain ——
  const topColor = color('#0b0b10');
  const bottomColor = color('#14141a');
  const gradientT = sub(1, uv().y);
  const gradient = mix(topColor, bottomColor, gradientT);

  const noise = fract(
    mul(sin(dot(positionWorld.xy, vec2(12.9898, 78.233))), 43758.5453123)
  );
  const grain = mul(sub(noise, 0.5), 0.015);
  const bgColorNode = add(gradient, vec3(grain));

  const bgGeometry = new PlaneGeometry(7, 5.5);
  const bgMaterial = new MeshBasicNodeMaterial({ colorNode: bgColorNode, transparent: false });
  const bgMesh = new ctx.THREE.Mesh(bgGeometry, bgMaterial);
  bgMesh.position.z = 0;
  root.add(bgMesh);

  // —— helpers ——
  function setAlpha(obj, value) {
    obj.traverse((o) => {
      if (o.material) {
        o.material.transparent = true;
        o.material.opacity = value;
      }
    });
  }

  function textBlock(content, opts, x, y, z, isHero = false) {
    const group = new Group();
    group.position.set(x, y + 0.4, z);

    const paper = ctx.fontAtlas.createText(content, opts);
    paper.position.z = isHero ? 0.02 : 0;
    setAlpha(paper, 0);
    group.add(paper);

    let shadow = null;
    if (isHero) {
      shadow = ctx.fontAtlas.createText(content, { ...opts, color: '#16161d' });
      shadow.position.z = -0.02;
      setAlpha(shadow, 0);
      group.add(shadow);
    }

    return { group, baseY: y };
  }

  function riseIn(block, delay) {
    const proxy = { y: block.baseY + 0.4, opacity: 0 };
    const tl = gsap.timeline({ delay });
    tl.to(proxy, {
      y: block.baseY,
      opacity: 1,
      duration: 0.7,
      ease: 'power3.out',
      onUpdate: () => {
        block.group.position.y = proxy.y;
        setAlpha(block.group, proxy.opacity);
      },
    });
    timelines.push(tl);
  }

  // —— type blocks ——
  const kickerBlock = textBlock(
    kickerText.toUpperCase(),
    { fontSize: 0.09, color: '#e8ecf2', align: 'left' },
    -3.1, 1.7, 0.05
  );
  root.add(kickerBlock.group);
  riseIn(kickerBlock, 0);

  const hero1Block = textBlock(
    heroLine1,
    { fontSize: 0.62, color: '#e8ecf2', align: 'left' },
    -3.1, 0.9, 0.05, true
  );
  root.add(hero1Block.group);
  riseIn(hero1Block, 0.08);

  const hero2Block = textBlock(
    heroLine2,
    { fontSize: 0.62, color: '#e8ecf2', align: 'left' },
    -3.1, 0.25, 0.05, true
  );
  root.add(hero2Block.group);
  riseIn(hero2Block, 0.16);

  const bodyBlock = textBlock(
    bodyText,
    { fontSize: 0.13, color: '#e8ecf2', align: 'left', maxWidthPx: 4.5 },
    -3.1, -0.8, 0.05
  );
  root.add(bodyBlock.group);
  riseIn(bodyBlock, 0.32);

  const captionBlock = textBlock(
    captionText,
    { fontSize: 0.09, color: '#e8ecf2', align: 'left' },
    -3.1, -1.9, 0.05
  );
  root.add(captionBlock.group);
  riseIn(captionBlock, 0.4);

  // —— accent underline rule ——
  const ruleWidth = 2.2;
  const ruleHeight = 0.05;
  const ruleGeometry = new PlaneGeometry(ruleWidth, ruleHeight);
  const ruleMaterial = new MeshBasicNodeMaterial({ colorNode: color('#ff2a38') });
  const ruleMesh = new ctx.THREE.Mesh(ruleGeometry, ruleMaterial);
  ruleMesh.position.x = ruleWidth / 2;

  const ruleGroup = new Group();
  ruleGroup.position.set(-3.1, -0.15, 0.06);
  ruleGroup.scale.x = 0;
  ruleGroup.add(ruleMesh);
  root.add(ruleGroup);

  const ruleTimeline = gsap.timeline({ delay: 0.86 });
  ruleTimeline.to(ruleGroup.scale, { x: 1, duration: 0.5, ease: 'power2.out' });
  timelines.push(ruleTimeline);

  // —— handlers & cleanup ——
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    root.traverse((o) => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
        else o.material.dispose();
      }
    });
  };

  return root;
}
